(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance)
select source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance
from jsonb_to_recordset($data$[{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Arts. 280 e 281 do CPP: suspeição e intérpretes","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 280 estende aos peritos, no que lhes for aplicável, as regras de suspeição dos juízes. O art. 281 equipara os intérpretes aos peritos para todos os efeitos. A pegadinha é confundir suspeição com impedimento ou atribuir ao dispositivo matéria relativa a testemunhas.","is_original":true,"legal_basis":["CPP, arts. 280 e 281"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — arts. 280 e 281","question_text":"Sobre os peritos e intérpretes, assinale a alternativa correta.\n\nA) O art. 280 estabelece que os peritos nunca podem ser considerados suspeitos.\nB) O art. 281 determina que os intérpretes não se submetem às regras aplicáveis aos peritos.\nC) O art. 280 estende aos peritos, no que for aplicável, as disposições sobre suspeição dos juízes; o art. 281 equipara os intérpretes aos peritos para todos os efeitos.\nD) O art. 281 permite que as partes escolham livremente o intérprete sem controle da autoridade.\nE) O art. 280 trata exclusivamente da incomunicabilidade de testemunhas.","content_status":"active","official_answer":"C","external_item_key":"pcac26-penal-proc-209-arts280-281-suspeicao-interprete","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 184 do CPP: perícia requerida pelas partes","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 184 permite negar perícia requerida pelas partes quando ela não for necessária ao esclarecimento da verdade, mas ressalva o exame de corpo de delito. Essa exceção é importante: quando a infração deixa vestígios, aplica-se a exigência do art. 158.","is_original":true,"legal_basis":["CPP, arts. 158 e 184"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 184","question_text":"Uma parte requer perícia complementar que não é necessária para esclarecer a verdade. O art. 184 do CPP estabelece que:\n\nA) toda perícia requerida deve ser realizada obrigatoriamente.\nB) a autoridade policial nunca pode avaliar a necessidade de perícia.\nC) o juiz só pode negar perícia se houver concordância de ambas as partes.\nD) o exame de corpo de delito pode ser negado quando houver testemunhas.\nE) salvo o exame de corpo de delito, o juiz ou a autoridade policial pode negar a perícia requerida quando ela não for necessária ao esclarecimento da verdade.","content_status":"active","official_answer":"E","external_item_key":"pcac26-penal-proc-210-art184-pericia-desnecessaria","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 14-A do CPP: defensor em investigação de uso de força letal","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 14-A tem âmbito específico: servidores vinculados às instituições do art. 144 da Constituição investigados por fatos ligados ao uso de força letal no exercício profissional. O investigado é citado e tem até 48 horas para constituir defensor; na falta, a instituição é comunicada para providenciar indicação nos termos dos parágrafos do artigo.","is_original":true,"legal_basis":["CPP, art. 14-A, §§ 1º a 6º"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 14-A","question_text":"Um policial civil é investigado por fato relacionado ao uso de força letal durante o exercício profissional. De acordo com o art. 14-A do CPP, assinale a alternativa correta.\n\nA) O dispositivo se aplica a qualquer investigação criminal envolvendo servidor público, independentemente do fato.\nB) Nas hipóteses legais, o investigado deve ser citado e pode constituir defensor em até 48 horas; se não o fizer, a instituição a que estava vinculado é comunicada para indicar defensor.\nC) A instituição deve indicar defensor antes da citação e sem prazo legal.\nD) O investigado só pode ser assistido pela Defensoria Pública, sendo vedado advogado constituído.\nE) O dispositivo elimina a investigação e determina arquivamento automático do inquérito.","content_status":"active","official_answer":"B","external_item_key":"pcac26-penal-proc-201-art14a-defensor","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 13-A do CPP: dados cadastrais","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 13-A autoriza requisição de dados e informações cadastrais em hipóteses criminais específicas que o próprio dispositivo enumera. Não é autorização genérica para acessar conteúdo de comunicações, interceptar conversas ou obter qualquer dado protegido sem observar a legislação aplicável.","is_original":true,"legal_basis":["CPP, art. 13-A e parágrafo único"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 13-A","question_text":"O art. 13-A do CPP permite, em crimes expressamente enumerados, que o delegado de polícia ou o membro do Ministério Público requisite:\n\nA) o conteúdo integral de conversas privadas de qualquer aplicativo, sem ordem judicial.\nB) a quebra automática de todo sigilo bancário de qualquer investigado.\nC) a interceptação telefônica por prazo indeterminado.\nD) dados e informações cadastrais da vítima ou de suspeitos aos órgãos públicos ou empresas indicados na lei.\nE) o histórico completo de localização de qualquer pessoa, em toda investigação.","content_status":"active","official_answer":"D","external_item_key":"pcac26-penal-proc-202-art13a-dados-cadastrais","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 13-B do CPP: meios técnicos de localização","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 13-B é específico para prevenção e repressão de crimes relacionados ao tráfico de pessoas. Prevê autorização judicial e meios técnicos de localização, com limites temporais. O § 2º, I, deixa claro que os sinais não permitem acesso ao conteúdo das comunicações, que depende de autorização judicial própria.","is_original":true,"legal_basis":["CPP, art. 13-B, caput e §§ 1º a 4º"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 13-B","question_text":"Em investigação de crime relacionado ao tráfico de pessoas, a autoridade policial necessita localizar vítima ou suspeito. Conforme o art. 13-B do CPP, a utilização de meios técnicos fornecidos por prestadoras de telecomunicações ou telemática:\n\nA) permite acesso automático ao conteúdo das comunicações, sem qualquer limite temporal.\nB) pode ser determinada por qualquer agente público, mesmo sem procedimento instaurado.\nC) depende das condições legais do artigo, inclusive autorização judicial, e os sinais de localização não autorizam acesso ao conteúdo das comunicações.\nD) é permitida para qualquer infração penal, sem relação com tráfico de pessoas.\nE) dispensa comunicação ao juiz mesmo quando a lei exige controle judicial.","content_status":"active","official_answer":"C","external_item_key":"pcac26-penal-proc-203-art13b-localizacao","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 155 do CPP: elementos informativos e prova judicial","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 155 determina que a convicção judicial se forme a partir da prova produzida em contraditório judicial. A lei ressalva provas cautelares, não repetíveis e antecipadas, mas não autoriza condenação baseada exclusivamente em elementos informativos comuns colhidos na investigação.","is_original":true,"legal_basis":["CPP, art. 155"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 155","question_text":"Durante a investigação, foram colhidos depoimentos e informações que não foram reproduzidos em juízo. Na sentença, o juiz pretende condenar o acusado exclusivamente com base nesses elementos. À luz do art. 155 do CPP:\n\nA) a condenação não pode se fundamentar exclusivamente nos elementos informativos da investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.\nB) a condenação é obrigatória sempre que houver relatório policial.\nC) os elementos do inquérito têm sempre o mesmo valor da prova produzida em contraditório judicial.\nD) o contraditório judicial é dispensável em qualquer crime.\nE) o juiz deve ignorar todas as provas produzidas durante a investigação, inclusive as não repetíveis.","content_status":"active","official_answer":"A","external_item_key":"pcac26-penal-proc-204-art155-prova-investigacao","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Arts. 158 e 167 do CPP: exame e vestígios desaparecidos","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 158 exige exame de corpo de delito direto ou indireto quando a infração deixa vestígios e afasta sua substituição pela confissão. Porém, se os vestígios desaparecerem e o exame não puder ser realizado, o art. 167 permite que a prova testemunhal supra sua falta.","is_original":true,"legal_basis":["CPP, arts. 158 e 167"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — arts. 158 e 167","question_text":"Uma infração deixou vestígios, mas eles desapareceram antes da realização do exame pericial. Qual solução está de acordo com o CPP?\n\nA) A confissão do investigado substitui obrigatoriamente o exame.\nB) A autoridade deve arquivar o procedimento por impossibilidade absoluta de prova.\nC) O exame indireto é sempre proibido.\nD) A prova testemunhal jamais pode ser utilizada para demonstrar a materialidade.\nE) A prova testemunhal pode suprir a falta do exame quando os vestígios tiverem desaparecido, conforme art. 167.","content_status":"active","official_answer":"E","external_item_key":"pcac26-penal-proc-205-art158-167-corpo-delito","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Cadeia de custódia: isolamento e liberação do local","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 158-C, § 2º, proíbe a entrada em locais isolados e a remoção de vestígios antes da liberação pelo perito responsável, sob pena de caracterização de fraude processual. A cadeia de custódia exige documentação cronológica de posse e manuseio, com acondicionamento adequado e individualizado.","is_original":true,"legal_basis":["CPP, arts. 158-A, 158-B e 158-C, § 2º"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — arts. 158-A a 158-C","question_text":"Ao chegar a um local de crime isolado, um servidor pretende recolher imediatamente um objeto que pode ser vestígio. Segundo as regras de cadeia de custódia do CPP, a conduta adequada é:\n\nA) recolher o objeto e só depois comunicar a perícia.\nB) preservar o isolamento e não remover vestígios antes da liberação pelo perito responsável, observando o registro das etapas da cadeia de custódia.\nC) permitir a entrada de qualquer pessoa desde que fotografe o local.\nD) dispensar registro de posse e manuseio quando o objeto for pequeno.\nE) acondicionar todos os vestígios juntos para facilitar o transporte.","content_status":"active","official_answer":"B","external_item_key":"pcac26-penal-proc-206-cadeia-custodia-isolamento","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 159 do CPP: ausência de perito oficial","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A regra é a realização por perito oficial com diploma de curso superior. Na falta dele, o § 1º admite duas pessoas idôneas com diploma superior, preferencialmente na área específica, e habilitação técnica relacionada ao exame. Não basta ser servidor ou testemunha sem qualificação.","is_original":true,"legal_basis":["CPP, art. 159, caput e § 1º"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 159, § 1º","question_text":"Na comarca não há perito oficial disponível para realizar determinado exame. Conforme o art. 159, § 1º, do CPP, o exame poderá ser realizado por:\n\nA) uma pessoa escolhida livremente pelo investigado, sem exigência de formação.\nB) qualquer servidor público, independentemente de qualificação.\nC) três testemunhas sem conhecimento técnico.\nD) duas pessoas idôneas com diploma de curso superior, preferencialmente na área específica, e habilitação técnica relacionada à natureza do exame.\nE) somente o juiz, pessoalmente.","content_status":"active","official_answer":"D","external_item_key":"pcac26-penal-proc-207-art159-perito-nao-oficial","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 180 do CPP: divergência entre peritos","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 180 determina que a divergência seja consignada no auto ou em laudos separados e prevê a nomeação de terceiro perito. Se o terceiro também divergir de ambos, a autoridade pode determinar novo exame por outros peritos. Não existe prevalência automática por antiguidade.","is_original":true,"legal_basis":["CPP, art. 180"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 180","question_text":"Dois peritos apresentam conclusões divergentes sobre o mesmo vestígio. Nos termos do art. 180 do CPP:\n\nA) a divergência deve ser registrada e a autoridade nomeará terceiro perito; se este também divergir, poderá ser determinado novo exame por outros peritos.\nB) o laudo do perito mais antigo prevalece automaticamente.\nC) o juiz deve escolher uma das conclusões sem fundamentação.\nD) a perícia é anulada automaticamente e não pode ser refeita.\nE) as partes decidem qual perito está correto, sem intervenção da autoridade.","content_status":"active","official_answer":"A","external_item_key":"pcac26-penal-proc-208-art180-divergencia-peritos","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","review_date":"2026-11-14","review_note":"Questão autoral revisada em face do texto atualizado do CPP; não é item oficial aplicado pelo IDECAN.","legal_source":"Código de Processo Penal, texto atualizado da Câmara dos Deputados"}}]$data$::jsonb)
as q(source_id uuid,syllabus_topic_id uuid,external_item_key text,contest_name text,contest_year integer,career_name text,exam_board text,subject text,subtopic text,tested_topic text,question_text text,official_answer text,explanation text,legal_basis jsonb,difficulty text,content_status text,is_original boolean,didactic_provenance jsonb)
